sub.on('message', (ch, msg) => broadcastLocalPeers(JSON.parse(msg)));`},{id:"fu-fs-2",title:"End-to-End Zero-Knowledge Payload Encryption (AES-GCM)",complexity:"Medium",category:"Security",description:"Encrypt character deltas on the client so the central server can route operations without reading raw user text.",architecturalImpact:"Guarantees enterprise zero-knowledge compliance for confidential documents."},{id:"fu-fs-3",title:"Periodic Snapshot Compaction & S3 Cold Storage Archive",complexity:"Medium",category:"Resilience",description:"Automatically compact the operation journal every 500 revisions and flush historical deltas to cold object storage.",architecturalImpact:"Prevents unbounded PostgreSQL / SQLite disk growth over multi-year document lifecycles."}],files:[{id:"f1",name:"otServer.ts",path:"server/otServer.ts",language:"typescript",type:"file",content:`// PrepMaster Sandbox: Server-side OT Engine
export interface Operation {
  type: 'insert' | 'delete';
  position: number;
  char?: string;
  revision: number;
  clientId: string;
}

export class DocumentSession {
  public content: string;
  public revision: number;
  private history: Operation[] = [];

  constructor(initialText = '') {
    this.content = initialText;
    this.revision = 0;
  }

  public applyClientOperation(incomingOp: Operation): { transformedOp: Operation; newRevision: number } {
    let transformed = { ...incomingOp };

    for (let i = incomingOp.revision; i < this.history.length; i++) {
      const pastOp = this.history[i];
      transformed = this.transform(transformed, pastOp);
    }

    if (transformed.type === 'insert' && transformed.char) {
      this.content =
        this.content.slice(0, transformed.position) +
        transformed.char +
        this.content.slice(transformed.position);
    } else if (transformed.type === 'delete') {
      this.content =
        this.content.slice(0, transformed.position) +
        this.content.slice(transformed.position + 1);
    }

    this.revision++;
    transformed.revision = this.revision;
    this.history.push(transformed);

    return { transformedOp: transformed, newRevision: this.revision };
  }

  public transform(op1: Operation, op2: Operation): Operation {
    const res = { ...op1 };
    if (op1.type === 'insert' && op2.type === 'insert') {
      if (op1.position > op2.position || (op1.position === op2.position && op1.clientId > op2.clientId)) {
        res.position += 1;
      }
    } else if (op1.type === 'insert' && op2.type === 'delete') {
      if (op1.position > op2.position) {
        res.position = Math.max(0, res.position - 1);
      }
    } else if (op1.type === 'delete' && op2.type === 'insert') {
      if (op1.position >= op2.position) {
        res.position += 1;
      }
    } else if (op1.type === 'delete' && op2.type === 'delete') {
      if (op1.position > op2.position) {
        res.position = Math.max(0, res.position - 1);
      }
    }
    return res;
  }
}`},{id:"f2",name:"Editor.tsx",path:"client/Editor.tsx",language:"typescript",type:"file",content:`// PrepMaster Sandbox: Client Collaborative React Component
